const { cliente_id, telefone, args = {} } = $json;
const faltando = ['data', 'hora', 'nome_paciente'].filter((k) => !args[k]);
if (faltando.length) return [{ json: { invalido: true, faltando } }];
return [{ json: { cliente_id, telefone, ...args, procedimento: args.procedimento ?? 'avaliação' } }];

const entrada = $('Validar args').item.json;
if (entrada.invalido) {
  return [{ json: { texto: `Para agendar preciso de: ${entrada.faltando.join(', ')}.`, dados: { erro: 'args_faltando', faltando: entrada.faltando } } }];
}
if (!$json.id) {
  return [{ json: { texto: 'Esse horário acabou de ser ocupado. Quer ver outros?', dados: { erro: 'horario_indisponivel' } } }];
}
return [{ json: { texto: `Consulta marcada para ${entrada.data} às ${entrada.hora} (${entrada.procedimento}).`, dados: { agendamento_id: $json.id } } }];
